r.append(R(7700186,"पैड थाई",
"मसालेदार, हल्के मीठे स्वाद वाले स्टिर-फ्राई किए हुए नूडल्स और सब्ज़ियाँ।",
"4","354 ग्राम",
["250 ग्राम सूखे चावल के नूडल्स","2 छोटे चम्मच रेपसीड तेल","6 हरे प्याज़, तिरछे 1 सेमी के टुकड़ों में कटे हुए","3 फांक लहसुन, कुचला हुआ","3 सेमी ताज़ा अदरक, कद्दूकस किया हुआ","1 थाई मिर्च, बारीक कटी हुई","1 लाल शिमला मिर्च, बारीक कटी हुई","1 तोरई, तीलियों जैसी कटी हुई","100 ग्राम जमे हुए बाक्ला (ब्रॉड बीन्स)","100 ग्राम बेबी पाक चोई, पत्तियाँ अलग की हुई","200 ग्राम अंकुरित मूँग (बीनस्प्राउट्स)","75 ग्राम रस में डिब्बाबंद अनानास, पानी निथारा हुआ, छोटा कटा हुआ","1 बड़ा चम्मच कम नमक वाला, ग्लूटेन-मुक्त सोया सॉस","1 नींबू (लाइम) का रस","15 ग्राम कटा हुआ धनिया","50 ग्राम बिना नमक वाली मूँगफली, मोटी कटी और भुनी हुई","1 नींबू (लाइम), फाँकों में कटा हुआ"],
["नूडल्स को पैकेट के निर्देशों के अनुसार पकाएँ, लगभग 3-5 मिनट। उन्हें ठंडे पानी में डालें, पानी निथारें और अलग रख दें।","एक बड़े पैन या कड़ाही में तेल गरम करें। हरे प्याज़ डालें और 3 मिनट स्टिर-फ्राई करें। लहसुन, अदरक और मिर्च डालें और 2 मिनट और स्टिर-फ्राई करें।","लाल शिमला मिर्च और तोरई डालें, एक मिनट और स्टिर-फ्राई करें, फिर बाक्ला और पाक चोई डालें। 1 मिनट स्टिर-फ्राई करें।","नूडल्स डालें, 2 मिनट स्टिर-फ्राई करें और अंकुरित मूँग, अनानास, सोया सॉस और नींबू (लाइम) का रस डालें। 2 मिनट और स्टिर-फ्राई करें और धनिया डालें।","एक कटोरे में डालें, ऊपर से मूँगफली और नींबू (लाइम) की फाँकें रखें।"],
["साइड डिश के लिए, आधे खीरे को सब्ज़ी छीलने वाले छीलक से रिबन की तरह काटें और ताज़ी धनिया की पत्तियाँ और थोड़ा नींबू (लाइम) निचोड़कर डालें।","इस व्यंजन में और प्रोटीन जोड़ने के लिए बाक्ला की जगह सोया बीन्स का उपयोग करें या कुछ टोफू डालें।",FV(2)]))
r.append(R(7705270,"समर बेरी पोसेट",
"यह स्टाइलिश पुडिंग बनाने में आसान है और गर्मियों की बेरीज़ का एकदम सही उत्सव है।",
"4","159 ग्राम",
["100 ग्राम रास्पबेरी","100 ग्राम ब्लूबेरी, ऊपर सजाने के लिए 4 बेरीज़ बचाकर रखें","2 बड़े चम्मच कम चीनी वाला स्ट्रॉबेरी जैम","300 ग्राम कम वसा वाला सादा दही","100 ग्राम हाफ़-फ़ैट क्रीम फ्रेश"],
["रास्पबेरी और ब्लूबेरी को जैम में डालें, काँटे से मसलें और अच्छी तरह मिलाएँ।","बेरी के आधे मिश्रण को दही और क्रीम फ्रेश में डालें और अच्छी तरह मिलाएँ।","बाक़ी बेरी के मिश्रण को चार गिलासों में बाँट दें, हर एक की तली में एक चम्मच डालें और अंदर की दीवारों पर थोड़ा-सा बहने दें।","दही के मिश्रण को गिलासों में बाँट दें, हर एक के ऊपर एक ब्लूबेरी रखें।"],
["अलग रूप के लिए ताज़ी खुबानी और खुबानी का जैम इस्तेमाल करें, या ऊपर से भुने हुए बादाम या कटे हुए हेज़लनट छिड़ककर कुरकुरापन जोड़ें।","हाफ़-फ़ैट क्रीम फ्रेश में डबल क्रीम की तुलना में एक-तिहाई से भी कम वसा होती है और इसमें ज़्यादा प्रोटीन भी होता है।","बेरीज़ में एंटीऑक्सिडेंट और विटामिन होते हैं – ख़ासकर विटामिन C। उन्हें अलग-अलग रंग देने वाले रंजकों में फ़ाइटोन्यूट्रिएंट और फ़्लेवोनॉइड होते हैं। ये फ़ाइबर का भी अच्छा स्रोत हैं।"]))
r.append(R(7709454,"मटन प्रोवेंसल",
"गहरे स्वाद वाली एक रेसिपी जो रसीले, मुलायम भेड़ के मांस का पूरा आनंद देती है। रविवार के लंच के लिए एकदम सही।",
"4","511 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","2 प्याज़, कटे हुए","1 लाल, 1 पीली और 1 हरी शिमला मिर्च, बड़े टुकड़ों में कटी हुई","4–6 फांक लहसुन, कुचला हुआ","2–3 तोरई","1 टहनी रोज़मेरी","1 टहनी थाइम","1 छोटा चम्मच सूखा ओरेगानो","20 ग्राम कटा हुआ ताज़ा पार्सले","1 x 400 ग्राम का डिब्बा कटे हुए टमाटर","400 ग्राम लीन भेड़ के मांस के स्टेक (हर एक 100 ग्राम)"],
["एक बड़े पैन में तेल डालें। प्याज़ डालें और मध्यम आँच पर 2 मिनट तक चलाएँ। इसके बाद लाल, पीली और हरी शिमला मिर्च डालकर 2 मिनट और चलाएँ। लहसुन और तोरई डालें और 2-3 मिनट चलाएँ।","सब्ज़ियों में रोज़मेरी, थाइम, ओरेगानो और पार्सले डालें, फिर टमाटर मिला दें। ढककर बीच-बीच में चलाते हुए 10 मिनट तक धीमी आँच पर पकाएँ।","इस बीच, भेड़ के मांस के स्टेक को ग्रिल करें और अच्छी तरह पकने तक पकाएँ।","मांस को आँच से उतारें, ढक दें और 3 मिनट तक आराम करने दें। प्रोवेंसल सॉस और हरे सलाद के साथ परोसें।"],
["इस व्यंजन की प्रोवेंसल सॉस किसी भी मांस, जैसे सूअर के स्टेक या टर्की एस्कालोप के साथ, या ग्रिल की हुई मछली के साथ अच्छी लगती है।",FV(4)]))
r.append(R(7714393,"सलाद निसुआज़",
"एक क्लासिक फ्रांसीसी रेसिपी, टूना प्रोटीन का बढ़िया स्रोत है और इसमें वसा कम होती है।",
"3","251 ग्राम",
["250 ग्राम नए आलू, बड़े टुकड़ों में कटे हुए","100 ग्राम पतली फ्रेंच बीन्स, पकी हुई","1 अंडा, चार भागों में कटा हुआ","2 टमाटर, फाँकों में कटे हुए","9 बीज निकाले हुए काले जैतून","3 एंकोवी फ़िलेट, लंबाई में आधे कटे हुए","1 नींबू का कद्दूकस किया छिलका और रस","2 छोटे चम्मच जैतून का तेल","150 ग्राम का ताज़ा टूना का टुकड़ा","ताज़ा पिसी हुई काली मिर्च"],
["आलू को 15-20 मिनट तक बस नरम होने तक उबालें, फिर ठंडा करने के लिए ठंडे पानी से धो लें।","एक कटोरे में आलू, बीन्स, अंडा, टमाटर, जैतून और एंकोवी को मिलाएँ। ऊपर से नींबू का छिलका और रस डालें, चलाएँ और 10 मिनट के लिए अलग रख दें।","फ्राइंग या ग्रिडल पैन को गरम होने तक गरम करें, टूना पर तेल लगाएँ और हर तरफ़ 2-3 मिनट तक सेकें। कुछ मिनट के लिए ठंडा होने दें, फिर मोटे स्लाइस में काट लें।","सलाद को थाली में सजाएँ, मसाला डालें और ऊपर से टूना रखें।"],
["शिशु, बच्चे, गर्भवती महिलाएँ, बुज़ुर्ग और बीमार लोग जैसे 'जोखिम वाले' समूहों को सीधे खाने के लिए तैयार, ठंडी स्मोक्ड या क्योर की हुई मछली खाने से बचना चाहिए। इसलिए, यदि यह आप पर लागू होता है तो यह रेसिपी उपयुक्त नहीं है।","यह रेसिपी टूना की जगह पोच किए हुए सैल्मन के टुकड़ों के साथ भी अच्छी बनती है।","यदि आपको एंकोवी पसंद नहीं हैं, तो उनकी जगह कुछ बारीक कटे सन-ड्राइड टमाटर डालें।","आप इसे उबले हुए बटेर के अंडों से बना सकते हैं, जो पहले से पके हुए मिलते हैं।","सेकी हुई टूना सबको पसंद नहीं आती और शायद उपयुक्त न हो, इसलिए आप उसे ग्रिडल पर ज़्यादा देर तक, पूरी तरह पकने तक, रख सकते हैं।",FV(0)]))
r.append(R(7716059,"शाकाहारी लज़ानिया",
"लज़ानिया पकाना और जमाना झंझट भरा हो सकता है। यह रेसिपी समय बचाती है, लेकिन स्वाद में कोई कमी नहीं छोड़ती। हमने इसे बजट के अनुकूल भी बनाया है।",
"6","408 ग्राम",
["1 बड़ा चम्मच जैतून का तेल","2 मध्यम आकार के प्याज़, छिले और बारीक कटे हुए","3 फांक लहसुन, छिले और बारीक कटे हुए","2 बड़े चम्मच टमाटर प्यूरी","3 x 400 ग्राम के डिब्बे कटे हुए टमाटर","250 ग्राम सफ़ेद पत्तागोभी","2 मुट्ठी सूखी तुलसी, पत्तियाँ तोड़ी और मोटी कटी हुई","75 ग्राम पानी में डिब्बाबंद हरी मसूर","250 ग्राम हाफ़-फ़ैट क्रीम फ्रेश","250 ग्राम साबुत अनाज की लज़ानिया शीट","50 ग्राम कद्दूकस किया हुआ हाफ़-फ़ैट चेडर चीज़"],
["ओवन को 200°C/400°F/गैस 6 पर पहले से गरम करें। टमाटर सॉस बनाने के लिए, एक बड़े सॉसपैन में तेल गरम करें और प्याज़, लहसुन और टमाटर प्यूरी को मध्यम आँच पर, चलाते हुए, दो-तीन मिनट तक भूनें।","टमाटर डालें, डिब्बों को थोड़े अतिरिक्त पानी से धोकर उसे भी सॉस में मिला दें। 20 मिनट तक धीमी आँच पर पकाएँ।","पत्तागोभी का मोटा डंठल हटाकर फेंक दें और पत्तियों को मोटा काट लें। इन्हें तुलसी के साथ सॉस में डालें और 5 मिनट तक पकाएँ, फिर मसूर और क्रीम फ्रेश मिलाएँ और आँच से उतार लें।","20 सेमी x 30 सेमी की बेकिंग ट्रे की तली में टमाटर सॉस की एक पतली परत डालें।","लज़ानिया शीट की एक परत बिछाएँ, फिर टमाटर सॉस की एक परत और थोड़ा कद्दूकस किया हुआ चीज़ छिड़कें। लज़ानिया शीट के साथ जारी रखें और जब तक शीट और सॉस ख़त्म न हो जाएँ, परतें दोहराते रहें। आख़िरी परत सॉस की होनी चाहिए जिसके ऊपर चीज़ हो।","ओवन में रखें और 30 से 40 मिनट तक बेक करें, या जब तक लज़ानिया सुनहरा न हो जाए और शीट नरम न हो जाएँ। बड़े सलाद के साथ परोसें।"],
["इस व्यंजन के कम कार्बोहाइड्रेट वाले संस्करण के लिए लज़ानिया शीट की जगह कटे हुए बैंगन का उपयोग करें।",FV(3)]))
r.append(R(7716634,"चार सिउ चिकन सीख और मीठी शिमला मिर्च",
"ये मीठी, चिपचिपी और मसालेदार सीखें स्वादिष्ट कैनपे बनाती हैं।",
"6","176 ग्राम",
["6 लकड़ी की सीखें","1 छिड़काव तेल","2–3 चिकन ब्रेस्ट (450 ग्राम), 24 छोटे चौकोर टुकड़ों में कटे हुए","2 ढेर वाले छोटे चम्मच चाइनीज़ फ़ाइव-स्पाइस","2 छोटे चम्मच तिल का तेल","2 छोटे चम्मच कम नमक वाला सोया सॉस","2 छोटे चम्मच बहता हुआ शहद","2 बड़ी लाल शिमला मिर्च, 24 टुकड़ों में कटी हुई","1 बड़ी पीली शिमला मिर्च, 12 टुकड़ों में कटी हुई",["सजाने के लिए","1 हरा प्याज़, कटा हुआ"],["सजाने के लिए","3 सेमी खीरा, आधा कटा और स्लाइस किया हुआ"],["सजाने के लिए","1 बड़ा चम्मच अनार के दाने (वैकल्पिक)"]],
["सीखों को 10 मिनट तक पानी में भिगो दें, ताकि वे जलें नहीं।","ओवन को 180°C/गैस 4 पर पहले से गरम करें और एक बड़ी बेकिंग ट्रे पर हल्का तेल लगाएँ।","चिकन को चाइनीज़ फ़ाइव-स्पाइस, तिल के तेल, सोया सॉस और शहद के साथ मिलाएँ, यह सुनिश्चित करते हुए कि सब पर बराबर लगे।","शिमला मिर्च और चिकन को बारी-बारी से सीखों में पिरोएँ और 8–10 मिनट तक बेक करें, या जब तक चिकन अंदर तक पक न जाए।","सर्विंग थाली में सजाएँ और ऊपर से हरा प्याज़, खीरा और अनार के दाने बिखेर दें।"],
["आप चिकन की जगह टर्की या सूअर का मांस – या कोई भी गूदेदार मछली – इस्तेमाल कर सकते हैं।","आप यह व्यंजन 24 घंटे पहले तक बनाकर रख सकते हैं, और चिकन को रात भर मैरिनेट होने के लिए छोड़ सकते हैं।"]))
r.append(R(7718325,"म्यूसली बेस वाला ब्लूबेरी योगर्ट केक",
"फ्रूट चीज़केक का एक हल्का, सेहतमंद विकल्प।",
"12","120 ग्राम",
["बेस के लिए: 150 ग्राम/5 औंस रोल्ड ओट्स","1 बड़ा चम्मच साबुत गेहूँ का आटा","1 बड़ा चम्मच दानेदार स्वीटनर","4 बड़े चम्मच सूरजमुखी तेल","योगर्ट और ब्लूबेरी टॉपिंग के लिए: 450 ग्राम/16 औंस ब्लूबेरी","1/2 नींबू, रस निकाला हुआ","3 बड़े चम्मच दानेदार स्वीटनर","500 ग्राम/18 औंस 0% फ़ैट वाला ग्रीक योगर्ट","250 ग्राम/9 औंस 3% फ़ैट वाला क्रीम चीज़, जैसे फ़िलाडेल्फ़िया लाइटेस्ट सॉफ़्ट चीज़"],
["बेस के लिए: ओवन को 180°C (160° फ़ैन)/350°F/गैस 4 पर पहले से गरम करें। 20 सेमी/8\" के स्प्रिंगफ़ॉर्म केक टिन की तली पर चिकनाई लगाएँ और ग्रीसप्रूफ़ पेपर बिछाएँ।","बेस की सारी सामग्री को एक मिक्सिंग बाउल में मिलाएँ। मिश्रण को तैयार टिन की तली में दबाकर बिछा दें।","10-12 मिनट तक बेक करें, जब तक ऊपर से जम न जाए और सुनहरा न हो जाए। टिन को ठंडा होने के लिए वायर रैक पर रख दें।","योगर्ट और ब्लूबेरी टॉपिंग के लिए: लगभग एक-चौथाई ब्लूबेरी को नींबू के रस और 1 बड़े चम्मच दानेदार स्वीटनर के साथ फ़ूड प्रोसेसर में प्यूरी कर लें।","इसे बारीक छन्नी से एक बड़े मिक्सिंग बाउल में छानें। ग्रीक योगर्ट, क्रीम चीज़ और बचा हुआ स्वीटनर डालें और गाढ़ा और मलाईदार होने तक अच्छी तरह फेंटें।","इसे बेक किए हुए बेस के ऊपर चम्मच से डालें, बराबर फैलाते हुए। ऊपर से बची हुई ब्लूबेरी रखें।","केक को ढककर 4 घंटे के लिए फ्रीज़ करें।","परोसने से लगभग 45 मिनट पहले केक को फ्रीज़र से निकाल लें ताकि वह नरम हो जाए।","टिन से निकालें और गरम, गीले चाकू से स्लाइस में काट लें।"],
["इस रेसिपी में कोई भी ताज़ी या जमी हुई बेरीज़ अच्छी लगेंगी।","आप कोई भी बिना मीठा सादा दही भी इस्तेमाल कर सकते हैं।","यह रेसिपी अतिरिक्त फलों के साथ परोसने पर बहुत अच्छी लगेगी। यदि आप चाहें, तो योगर्ट के मिश्रण में सारी साबुत ब्लूबेरी इस्तेमाल करके देखें। इससे मुक्त शर्करा भी कम होगी।","अनुशंसित मात्रा के लिए अपने स्वीटनर के पैकेट को दोबारा जाँच लें।",FV(0)]))
r.append(R(7719810,"बीन्स और मशरूम एन्चिलाडास",
"पेट भरने वाला पारिवारिक भोजन जो बनाने में आसान, सस्ता और पौष्टिक है।",
"4","578 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","2 प्याज़, कटे हुए","2 फांक लहसुन, कुचला हुआ","1 पीली शिमला मिर्च, कटी हुई","250 ग्राम मशरूम, कटे हुए","2-3 छोटे चम्मच मिर्च पाउडर (हल्का या तीखा, स्वादानुसार)","1 ढेर वाला छोटा चम्मच ओरेगानो","1 ढेर वाला छोटा चम्मच जीरा","1 x 400 ग्राम का डिब्बा कटे हुए टमाटर","2 बड़े चम्मच टमाटर प्यूरी","1 गाजर, कद्दूकस की हुई","1 x 400 ग्राम का डिब्बा मिले-जुले बीन्स, पानी निथारे और धोए हुए","1 x 400 ग्राम का डिब्बा हरी मसूर","4 बड़े साबुत गेहूँ के टॉर्टिला (हर एक लगभग 65 ग्राम)","200 ग्राम कम वसा वाला दही","75 ग्राम कम वसा वाला चेडर"],
["ओवन को 180°C/गैस मार्क 4 पर पहले से गरम करें। सॉसपैन में तेल गरम करें, फिर प्याज़ को 2-3 मिनट तक नरम होने तक भूनें। लहसुन, पीली शिमला मिर्च, मशरूम, मिर्च पाउडर, ओरेगानो और जीरा डालें। सारी सामग्री को चलाकर मिला दें।","टमाटर, टमाटर प्यूरी और गाजर डालें। अच्छी तरह मिलाएँ। उबाल आने दें, आँच धीमी करें, ढक्कन से ढकें, फिर बीच-बीच में चलाते हुए 10 मिनट तक पकाएँ।","मिले-जुले बीन्स और हरी मसूर डालें, मिलाएँ, फिर दोबारा उबाल तक लाएँ। चलाएँ और आँच से उतार लें।","एक बड़ी ओवन-सुरक्षित डिश की तली में चिली मिश्रण के 4 बड़े चम्मच फैला दें। टॉर्टिला को बोर्ड पर बिछाएँ और बाक़ी चिली मिश्रण को उनमें बाँट दें। सिरों को मोड़ें और बंद करने के लिए लपेट दें। उन्हें ओवन-सुरक्षित डिश में एक कतार में रखें।","दही और कद्दूकस किया हुआ चेडर मिलाएँ और एन्चिलाडास के ऊपर जगह-जगह रख दें। 12-15 मिनट तक हल्का भूरा होने तक बेक करें। सलाद के साथ परोसें।"],
["चिली का मिश्रण बेक किए हुए शकरकंद या चावल के साथ परोसने पर बहुत अच्छा लगता है, या इसे ज़्यादा सेहतमंद नाचोस बनाने के लिए टॉर्टिला चिप्स पर चम्मच से डालें।","चिली का भरावन फ्रीज़ भी किया जा सकता है।","आपको सामग्री में बताई गई जड़ी-बूटियाँ और मसाले इस्तेमाल करना ज़रूरी नहीं है; आप अपनी रसोई के भंडार में उपलब्ध किसी भी चीज़ का उपयोग कर सकते हैं।",FV(5)]))
r.append(R(7720686,"जड़ी-बूटियों वाली मैकरल",
"जड़ी-बूटियों और खट्टे फलों के भरपूर स्वाद के साथ, यह खुले में खाने के लिए एकदम सही व्यंजन है और ताज़े टमाटर के सलाद के साथ परोसने पर बहुत स्वादिष्ट लगता है।",
"4","321 ग्राम",
["4 छोटी मैकरल (हर एक लगभग 90 ग्राम)","1 स्लाइस सोया और अलसी की ब्रेड (कोई भी साबुत गेहूँ की ब्रेड चलेगी)","1 बड़ा चम्मच कटा हुआ पार्सले","1 बड़ा चम्मच कटा हुआ ताज़ा धनिया","1 नींबू और 1 संतरे का बारीक कद्दूकस किया छिलका","आधा छोटा चम्मच पिसा जीरा","आधा छोटा चम्मच पिसा धनिया","एक चुटकी मिर्च के फ्लेक्स","आधा छोटा चम्मच जैतून का तेल","100 मिली फ़िश, वेजिटेबल या चिकन स्टॉक",["टमाटर के सलाद के लिए","6–8 मध्यम आकार के टमाटर, कटे हुए (500 ग्राम)"],["टमाटर के सलाद के लिए","आधा मध्यम लाल प्याज़, बहुत पतला कटा हुआ"],["टमाटर के सलाद के लिए","1 बड़ा चम्मच प्रत्येक कटा हुआ पार्सले और धनिया"],["टमाटर के सलाद के लिए","1 नींबू या आधे संतरे का रस"],["टमाटर के सलाद के लिए","ताज़ा पिसी हुई काली मिर्च"],["टमाटर के सलाद के लिए","120 ग्राम रॉकेट (अरुगुला)"]],
["ओवन को 200ºC/गैस 6 पर पहले से गरम करें।","मैकरल के सिर हटा दें, पेट के साथ चीरें और अंतड़ियाँ निकाल दें। अच्छी तरह धोएँ और किचन पेपर से थपथपाकर सुखा लें।","हर मछली को खोलकर त्वचा की तरफ़ ऊपर रखें और रीढ़ की हड्डी को ढीला करने के लिए पूरी लंबाई पर मज़बूती से दबाएँ। सावधानी से हड्डी को गूदे से उठाएँ और पूँछ के सिरे पर काट दें, पूँछ को वैसे ही रहने दें। धोकर सुखा लें।","फ़ूड प्रोसेसर में ब्रेड को पार्सले, ताज़े धनिये, छिलकों, जीरे, पिसे धनिये, मिर्च के फ्लेक्स और जैतून के तेल के साथ तब तक पल्स करें जब तक कि बारीक चूरा न बन जाए।","मैकरल को गूदे की तरफ़ ऊपर करके एक बड़ी बेकिंग डिश में सजाएँ और ब्रेड के चूरे से ढक दें। स्टॉक को मैकरल के चारों ओर डालें, उनके ऊपर नहीं।","8-10 मिनट तक पकाएँ, जब तक मछली अपारदर्शी न हो जाए। इस बीच, सलाद की सारी सामग्री को मिला लें।","मैकरल को बेकिंग डिश के रस, सलाद और रॉकेट की पत्तियों के साथ परोसें।"],
["यदि आपको पूरी मछली से निपटना पसंद नहीं है, तो मैकरल फ़िलेट भी उतने ही अच्छे लगते हैं।","रिवर कॉबलर, कॉड, तिलापिया या ट्राउट जैसे अन्य मछली के फ़िलेट इस जड़ी-बूटियों वाली परत के साथ बढ़िया लगते हैं।",FV(2)]))
r.append(R(7721061,"पेपरिका रोस्ट जड़ वाली सब्ज़ियाँ",
"रोस्ट के लिए एकदम सही संगत, हल्के मसाले वाली ये जड़ वाली सब्ज़ियाँ एक गरमाहट देने वाली साइड डिश हैं।",
"6","221 ग्राम",
["500 ग्राम ताज़ा चुकंदर","300 ग्राम गाजर, टुकड़ों में कटी हुई","500 ग्राम शकरकंद, चौकोर कटा हुआ","आधे नींबू का रस","3 छोटे चम्मच स्मोक्ड पेपरिका","2 छोटे चम्मच रेपसीड तेल"],
["चुकंदर, गाजर और शकरकंद को एक कटोरे में डालें।","नींबू का रस और स्मोक्ड पेपरिका डालें और अच्छी तरह मिलाएँ, सारी सब्ज़ियों पर पूरी तरह लगा दें।","सब्ज़ियों को बराबर बिछाने से पहले एक बड़ी बेकिंग ट्रे पर रेपसीड तेल लगाएँ। 180C/गैस 5 पर 30-35 मिनट तक बेक करें, बीच में एक-दो बार मिलाएँ ताकि सब्ज़ियाँ बराबर पकें।"],
["स्वीडिश शलजम, साधारण आलू, बटरनट स्क्वैश या प्याज़ के बड़े टुकड़ों जैसी अन्य सब्ज़ियाँ भी रोस्ट करके देखें।","परोसने से ठीक पहले, मुट्ठी भर ताज़ी कटी जड़ी-बूटियाँ, जैसे धनिया, पार्सले, चाइव्स या पुदीना डालें।",FV(2)]))
r.append(R(7722208,"पालक और वेन्सलीडेल से भरा पोर्टोबेलो मशरूम",
"पालक और चीज़ से सजा यह मशरूम कैप एक स्वादिष्ट, बनाने में आसान स्टार्टर या साइड डिश है।",
"1","348 ग्राम",
["1 छोटा प्याज़, बारीक कटा हुआ","1 छोटा चम्मच जैतून का तेल","1 बड़ा पोर्टोबेलो मशरूम","100 ग्राम बेबी पालक की पत्तियाँ","एक अच्छी चुटकी सूखा थाइम","1 फांक लहसुन, कुचला हुआ","1 छोटा चम्मच डिजॉन सरसों","1 स्लाइस साबुत गेहूँ की ब्रेड, चूरा की हुई","एक अच्छी चुटकी काली मिर्च","25 ग्राम वेन्सलीडेल चीज़, छोटे टुकड़ों में कटा हुआ (या चेडर, फ़ेटा या बकरी का चीज़)"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें।","एक पैन में प्याज़ को तेल के साथ डालें और अच्छी तरह भूरा होने तक पकाएँ।","मशरूम का डंठल निकालें, उसे काटें और प्याज़ में पालक, थाइम और लहसुन के साथ डाल दें।","जब पालक मुरझा जाए, तो सरसों, ब्रेड और काली मिर्च डालें और अच्छी तरह मिलाएँ। ढक दें और दो-तीन मिनट के लिए छोड़ दें ताकि ब्रेड सारे स्वाद सोख ले।","भरावन को फिर से मिलाएँ और फिर उसे मशरूम कैप पर ढेर लगा दें।","चीज़ को ऊपर बराबर बिखेरें, उसे भरावन में दबाएँ, और 10 मिनट बेक करें।"],
["जमा हुआ पालक आपके फ्रीज़र में रखने के लिए एक उपयोगी सामग्री है। कटे हुए की जगह पत्तों वाला पालक देखें, और इस्तेमाल से पहले हमेशा उसे पिघला लें ताकि आप अतिरिक्त पानी निचोड़ सकें।","ताज़े पालक की पत्तियाँ लेट्यूस का बढ़िया विकल्प हैं।","यदि आपको वेन्सलीडेल पसंद नहीं है, तो उतनी ही मात्रा में चेडर, फ़ेटा या बकरी का चीज़ डालकर देखें।","फ्रीज़ करने के निर्देश: हर मशरूम के बीच ग्रीसप्रूफ़ पेपर रखकर फ्रीज़ करें। 1 घंटे तक पिघलाएँ, फिर माइक्रोवेव या मध्यम गरम ओवन में गरम करें।",FV(3)]))
r.append(R(7724336,"नारियल चावल की खीर",
"चावल की खीर का एक कम वसा वाला संस्करण",
"3","204 ग्राम",
["100 ग्राम बासमती चावल","400 मिली बिना मीठा नारियल दूध पेय","300 मिली बिना मीठा सोया दूध","4 छोटे चम्मच दानेदार स्वीटनर","कुछ बूँदें वनीला एसेंस","1 बड़ा चम्मच भुना हुआ नारियल"],
["भुने हुए नारियल को छोड़कर सारी सामग्री एक छोटे पैन में डालें। धीमी आँच पर रखें और चावल के नरम होने तक 20–25 मिनट बहुत धीरे-धीरे पकाएँ।","ऊपर से भुना हुआ नारियल डालकर परोसें।"],
["ढक्कन लगाकर धीमी आँच पर पकाएँ; यदि चावल पैन में चिपकने लगें, तो आप हमेशा थोड़ा और सोया दूध या पानी डाल सकते हैं।","यदि आपको भुना हुआ नारियल न मिले, तो बस 1 बड़ा चम्मच सूखा नारियल (डेसिकेटेड) एक सूखे फ्राइंग पैन में डालें और मध्यम आँच पर 2-3 मिनट तक भूरा होने तक चलाते रहें।"]))
r.append(R(7727187,"अतिरिक्त फलों वाले हॉट क्रॉस बन",
"ये हॉट क्रॉस बन साबुत गेहूँ के आटे और अतिरिक्त फलों से बने हैं। इनमें पारंपरिक स्वाद पूरा है, और ये पेट भरने वाले और संतोषजनक हैं।",
"12","100 ग्राम",
["500 ग्राम साबुत गेहूँ का आटा, गूँधने के लिए 1 बड़ा चम्मच और","1.5 छोटा चम्मच/7 ग्राम का सैशे फ़ास्ट-एक्शन सूखा यीस्ट","50 ग्राम नरम भूरी चीनी","2 ढेर वाले छोटे चम्मच पिसा मिक्स्ड स्पाइस","1 पका केला, मसला हुआ","1 अंडा, फेंटा हुआ","1 नींबू का कद्दूकस किया छिलका","1 संतरे का कद्दूकस किया छिलका","1 सेब, बीज निकालकर कद्दूकस किया हुआ, लेकिन छिला नहीं","200 मिली गुनगुना दूध","125 ग्राम मिले-जुले सूखे फल","2 छोटे चम्मच सूरजमुखी तेल"],
["ओवन को 190°C/गैस 5 पर पहले से गरम करें। एक बड़े कटोरे में आटा, यीस्ट, चीनी और मिक्स्ड स्पाइस मिलाएँ।","दूसरे कटोरे में केला, अंडा, कद्दूकस किया नींबू का छिलका, संतरे का छिलका और सेब फेंटें।","लकड़ी के चम्मच से गुनगुने दूध को धीरे-धीरे आटे के मिश्रण में मिलाएँ, फिर अंडे और केले का मिश्रण मिला दें।","इस चिपचिपे आटे को एक हाथ से गूँधना शुरू करें, फिर इसे हल्के आटे लगे काम की सतह पर निकाल लें। आटे को अपनी हथेली के निचले हिस्से से खींचें और दबाएँ, उसे मोड़ें और यदि वह ज़्यादा चिपक रहा हो तो थोड़ा और आटा छिड़कें। 5–10 मिनट तक गूँधें जब तक आटा चिकना और लचीला न हो जाए।","आटे को चपटा करें और उस पर सूखे फल छिड़कें, मोड़ें और दो मिनट और गूँधें जब तक सूखे फल मिल न जाएँ।","एक बड़े कटोरे में एक छोटा चम्मच तेल हल्का लगाएँ और आटे को कटोरे में रखें, हल्के तेल लगे क्लिंग फ़िल्म से ढकें और 1 घंटे तक गरम जगह पर फूलने के लिए छोड़ दें (एयरिंग कपबोर्ड बढ़िया रहता है) इसका आकार दोगुना हो जाना चाहिए।","मिश्रण को 12 गोल बन में बाँटें, उन्हें एक या दो हल्के तेल लगी बेकिंग शीट पर फैलने की भरपूर जगह छोड़ते हुए सजाएँ। फिर से प्लास्टिक फ़िल्म या साफ़ किचन टॉवल से ढकें और एक घंटे और फूलने के लिए छोड़ दें।","हर बन पर तेज़ चाकू से गहरा क्रॉस काटें, फिर 20–25 मिनट तक सुनहरा भूरा होने तक बेक करें।"],
["इन्हें ओवन से निकलते ही गरम खाएँ या ठंडा करके एयरटाइट डिब्बे में 2–3 दिन तक रखें। बन को माइक्रोवेव में गरम करें, या काटकर टोस्ट करें।","ऊपर सफ़ेद क्रॉस बनाने के लिए, 50–60 ग्राम आटे को 2 बड़े चम्मच पानी के साथ मिलाकर पेस्ट बनाएँ, बेलें और पट्टियों में काटें। फिर पानी लगाकर ओवन में रखने से ठीक पहले बन पर चिपका दें।","फ्रीज़ करने के निर्देश: पकाने के बाद फ्रीज़ किया जा सकता है। ज़रूरत के अनुसार उपयोग के लिए अलग-अलग लपेटी हुई सर्विंग में फ्रीज़ करें। 2 घंटे तक पिघलाएँ, या माइक्रोवेव में।"]))
r.append(R(7727427,"फ़िश पाई",
"स्मोक्ड पेपरिका से आने वाले हल्के धुएँदार स्वाद वाली स्वादिष्ट रूप से नम फ़िश पाई। यह पारंपरिक फ़िश पाई की तुलना में कम वसा वाली और कम नमकीन है, लेकिन उतनी ही स्वादिष्ट।",
"6","382 ग्राम",
["1 किलो शकरकंद, बड़े टुकड़ों में कटा हुआ","2 छोटे चम्मच रेपसीड तेल","2 लीक, लंबाई में आधे कटे, फिर कटे हुए","1 ढेर वाला बड़ा चम्मच मैदा","1 फ़िश स्टॉक क्यूब","400 मिली स्किम्ड दूध","एक अच्छी चुटकी सफ़ेद मिर्च","25 ग्राम ताज़ा पार्सले, कटा हुआ (और सजाने के लिए थोड़ा-सा)","1 ढेर वाला छोटा चम्मच स्मोक्ड पेपरिका","300 ग्राम पोलक मछली, चौकोर टुकड़ों में कटी हुई","300 ग्राम सैल्मन, चौकोर टुकड़ों में कटी हुई","एक चुटकी काली मिर्च"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। शकरकंद को 15-20 मिनट तक नरम होने तक उबालें और पानी निथार लें।","एक सॉसपैन में धीमी से मध्यम आँच पर तेल गरम करें और लीक को बार-बार चलाते हुए, नरम होने तक, लगभग 7-8 मिनट भूनें।","लीक पर मैदा छिड़कें और स्टॉक क्यूब को ऊपर से चूरा करके डालें। लगभग एक मिनट तक अच्छी तरह मिलाएँ जब तक लीक पर मैदा न लिपट जाए।","धीरे-धीरे एक-चौथाई दूध मिलाएँ जब तक यह काफ़ी गाढ़ा न हो जाए, फिर लगातार चलाते हुए बाक़ी दूध धीरे-धीरे मिलाएँ जब तक कि उबाल न आ जाए। सफ़ेद मिर्च और पार्सले डालें और आँच से उतार लें।","शकरकंद को अच्छी तरह मैश करें और स्मोक्ड पेपरिका मिला दें।","लीक सॉस को ओवन-सुरक्षित डिश में डालें और मछली को इस तरह सजाएँ कि वह बराबर फैली हो, उसे सॉस में दबा दें। ऊपर से शकरकंद डालें और 25-35 मिनट तक बेक करें, जब तक कि सॉस शकरकंद के बीच से बुलबुले के साथ न निकलने लगे, ऊपर से बचा हुआ पार्सले और काली मिर्च छिड़कें।"],
["आप अलग-अलग फ़िश पाई बना सकते हैं – डिनर पार्टी के लिए बढ़िया, और इसमें कुछ झींगे या कटे हुए मशरूम भी डालकर देखें।","यह हैडॉक या रिवर कॉबलर जैसी अन्य मछलियों के साथ भी अच्छी बनती है।","आप आधा शकरकंद और आधा आलू इस्तेमाल कर सकते हैं।",FZ+"फिर फ्रिज में पिघलाएँ और भाप निकलने तक दोबारा गरम करें।",FV(2)]))
r.append(R(7731476,"जड़ी-बूटियों वाली सब्ज़ी क्विश",
"ताज़ा पार्सले और चाइव्स इस शानदार शाकाहारी क्विश को गर्मियों का असली स्वाद देते हैं! यह रेसिपी स्लिमिंग वर्ल्ड के साथ साझेदारी में चुनी गई थी।",
"2","399 ग्राम",
["कम कैलोरी वाला कुकिंग स्प्रे","1 छोटा प्याज़, बारीक कटा हुआ","1 फांक लहसुन, बारीक कटा हुआ","1 तोरई, बारीक कटी हुई","100 ग्राम चेरी टमाटर, आधे कटे हुए","1 बड़ा चम्मच प्रत्येक कटा हुआ ताज़ा पार्सले और चाइव्स, परोसने के लिए थोड़ा और","जार से 100 ग्राम नमकीन पानी में भुनी लाल शिमला मिर्च, पानी निथारी और मोटी कटी हुई","150 ग्राम फ़ैट-फ़्री सादा कॉटेज चीज़","4 मध्यम अंडे, हल्के फेंटे हुए"],
["ओवन को 200°C/फ़ैन 180°C/गैस 6 पर पहले से गरम करें। एक नॉन-स्टिक, ओवन-सुरक्षित 18 सेमी फ़्लैन या पाई डिश पर कम कैलोरी वाले कुकिंग स्प्रे का हल्का छिड़काव करें।","एक नॉन-स्टिक फ्राइंग पैन पर कम कैलोरी वाले कुकिंग स्प्रे के दो-तीन पंप छिड़कें और उसे मध्यम आँच पर रखें। प्याज़, लहसुन, तोरई और टमाटर को 6-8 मिनट तक या नरम होने तक स्टिर-फ्राई करें। आँच से उतार लें। जड़ी-बूटियाँ और शिमला मिर्च मिलाएँ, फिर कॉटेज चीज़ और अंडे को मिलाकर उसमें डालें। हल्की काली मिर्च से स्वाद बनाएँ और चम्मच से फ़्लैन या पाई डिश में डालें।","30-35 मिनट तक बेक करें, या जब तक हल्का सुनहरा और अंदर तक पक न जाए। ऊपर से अतिरिक्त जड़ी-बूटियाँ बिखेरें और सलाद के साथ परोसें।"],
[FV(2)]))
save(6,r)
